#!/usr/bin/env python3
"""Main entry point for the prompt-to-bot service."""

import asyncio
import logging
import os
import socket
import sys
import threading
import time
from pathlib import Path
from typing import Optional

import structlog
from sanic import Blueprint, HTTPResponse, Sanic
from sanic.request import Request
from sanic_openapi.openapi3.blueprint import blueprint_factory

import rasa.telemetry
from rasa.builder import config
from rasa.builder.logging_utils import (
    attach_request_id_processor,
    collecting_logs_processor,
    collecting_validation_logs_processor,
    log_request_end,
    log_request_start,
)
from rasa.builder.service import bp
from rasa.builder.workspace import WorkspaceManager
from rasa.core.channels.inspector import InspectorInputChannel
from rasa.core.channels.rest import RestInput
from rasa.model_manager.warm_rasa_process import warmup
from rasa.utils.common import configure_logging_and_warnings
from rasa.utils.cors import configure_cors
from rasa.utils.log_utils import configure_structlog
from rasa.utils.sanic_error_handler import register_custom_sanic_error_handler

structlogger = structlog.get_logger()


def setup_logging() -> None:
    """Setup logging configuration."""
    log_level = logging.DEBUG

    configure_logging_and_warnings(
        log_level=log_level,
        logging_config_file=None,
        warn_only_once=True,
        filter_repeated_logs=True,
    )

    configure_structlog(
        log_level,
        include_time=True,
        additional_processors=[
            attach_request_id_processor,
            collecting_logs_processor,
            collecting_validation_logs_processor,
        ],
    )


def setup_input_channel() -> InspectorInputChannel:
    """Setup the input channel for chat interactions."""
    inspector_credentials = config.get_default_credentials().get(
        InspectorInputChannel.name()
    )
    return InspectorInputChannel.from_credentials(credentials=inspector_credentials)


def setup_openapi_blueprint() -> Blueprint:
    """Return the Swagger UI blueprint with uniquely named static routes."""
    # sanic-openapi 21.12 (last release) calls Blueprint.static() twice without
    # `name=`, so both routes are named "openapi.static". Sanic rejects
    # duplicate route names since 23.3, which aborts startup:
    # https://github.com/sanic-org/sanic/issues/2674
    oas3_blueprint = blueprint_factory()
    oas3_blueprint._future_statics = {
        static._replace(name=f"{static.name}_{index}")
        for index, static in enumerate(oas3_blueprint._future_statics)
    }
    return oas3_blueprint


def setup_middleware(app: Sanic) -> None:
    """Setup middleware for request/response processing."""

    @app.middleware("request")
    async def log_request(request: Request) -> None:
        # store start time on request ctx for later latency calculation
        request.ctx._start_time = log_request_start(request)

    @app.middleware("response")
    async def log_response(request: Request, response: HTTPResponse) -> None:
        try:
            start = getattr(request.ctx, "_start_time", None)
            if start is None:
                # If for some reason the request middleware didn't run
                start = log_request_start(request)
            # propagate correlation id for clients
            correlation_id = getattr(request.ctx, "correlation_id", None)
            if correlation_id:
                response.headers["X-Correlation-Id"] = correlation_id
            log_request_end(request, response, start)
        except Exception:
            # avoid breaking response path
            pass


def setup_langfuse() -> None:
    """Setup langfuse configuration.

    No ``tracer_provider`` is passed, so the SDK attaches its span processor to
    the global OpenTelemetry provider — which is what lets Copilot v2's
    pydantic-ai spans reach Langfuse without an adapter.

    Note for any future move to an isolated provider: the SDK's ``shutdown``
    force-flushes ``get_tracer_provider()`` — the *global* one — not whichever
    provider it was constructed with. Passing an isolated provider therefore
    needs its own explicit ``force_flush`` on shutdown, or the last batch of
    Copilot spans is dropped.
    """
    from rasa.builder.telemetry.langfuse_integration.langfuse_compat import (
        require_langfuse,
    )
    from rasa.tracing.constants import (
        LANGFUSE_ENV_VAR_PUBLIC_KEY,
        LANGFUSE_ENV_VAR_SECRET_KEY,
    )

    require_langfuse()

    from langfuse import Langfuse  # noqa: TID251

    public_key = config.LANGFUSE_PUBLIC_KEY
    secret_key = config.LANGFUSE_SECRET_KEY

    Langfuse(
        public_key=public_key,
        secret_key=secret_key,
        host=config.LANGFUSE_HOST,
        additional_headers={
            config.DEPLOYMENT_STACK_HEADER_NAME: config.DEPLOYMENT_STACK
        },
        environment=config.DEPLOYMENT_STACK or config.LANGFUSE_DEFAULT_ENVIRONMENT,
    )

    # Soft paths (``@observe``, ``with_langfuse``) gate on these env vars.
    # Builder may resolve keys from module config / license fallback without
    # writing them to the environment — export them so tracing stays enabled.
    if public_key:
        os.environ[LANGFUSE_ENV_VAR_PUBLIC_KEY] = public_key
    if secret_key:
        os.environ[LANGFUSE_ENV_VAR_SECRET_KEY] = secret_key


def create_app(workspaces_root: str) -> Sanic:
    """Create and configure the Sanic app.

    Args:
        workspaces_root: Folder holding one sub-folder per agent.
    """
    app = Sanic("BotBuilderService")
    # Must precede `app.blueprint(bp)`: registering a blueprint adds its
    # exception handlers to the current error handler, and replacing the
    # handler afterwards silently drops them (400/409s become 500s).
    register_custom_sanic_error_handler(app)

    # Basic app configuration
    app.config.REQUEST_TIMEOUT = 60  # 1 minute timeout

    structlogger.debug(
        "builder.main.create_app",
        workspaces_root=workspaces_root,
        rasa_version=rasa.__version__,
    )

    app.ctx.workspace_manager = WorkspaceManager(Path(workspaces_root))

    # Set up input channel and store in app context
    app.ctx.input_channel = setup_input_channel()

    # The builder never loads an agent in its own process, so this stays None
    # and every reader (routes, channels, license checks) sees "no agent loaded".
    app.ctx.agent = None

    # Register the blueprint
    app.blueprint(bp)

    # OpenAPI docs
    app.blueprint(setup_openapi_blueprint())
    app.config.API_TITLE = "Bot Builder API"
    app.config.API_VERSION = rasa.__version__
    app.config.API_DESCRIPTION = (
        "API for building conversational AI bots from prompts and templates. "
        "The API allows to change the assistant and retrain it with new data."
    )

    # Setup middleware
    setup_middleware(app)

    configure_cors(app, cors_origins=config.CORS_ORIGINS)

    # Register input channel webhooks
    from rasa.core import channels

    channels.channel.register(
        [app.ctx.input_channel, RestInput()], app, route="/webhooks/"
    )

    # Warm the document-retrieval backends (CALM v1 and Mantle) once at startup
    # so they live for the whole service session. They feed the copilot's
    # doc-search tool, which reads these process-wide singletons.
    @app.after_server_start
    async def init_retrieval_on_startup(
        app: Sanic, loop: asyncio.AbstractEventLoop
    ) -> None:
        """Build the document retrievers once when the server starts."""
        try:
            from rasa.builder.copilot.pydantic_ai.document_search import (
                warm_retrievers,
            )

            warm_retrievers()
            structlogger.info("Document retriever initialized on server startup")
        except Exception as e:
            structlogger.warning(
                "Failed to initialize document retriever on server startup",
                error=str(e),
            )

    # Flush buffered Langfuse spans while the process is still healthy. The SDK
    # registers its own ``atexit`` hook, so this is not the only safety net —
    # but that one runs during interpreter teardown, where module state may
    # already be gone and failures are swallowed silently. Doing it here, on a
    # live event loop, makes the flush observable and its failures loggable.
    # ``shutdown`` unregisters the atexit hook, so the work is never repeated.
    #
    # ``after_server_stop`` rather than ``before_server_stop``: Sanic runs
    # before_stop -> cleanup -> after_stop -> loop.close, so this is the latest
    # hook that still has a live event loop to await on — the most spans
    # possible have been ended, and ``asyncio.to_thread`` still works.
    @app.after_server_stop
    async def shutdown_langfuse(app: Sanic, loop: asyncio.AbstractEventLoop) -> None:
        """Flush pending Langfuse spans and stop its exporter threads."""
        from rasa.builder.telemetry.langfuse_integration.langfuse_compat import (
            with_langfuse,
        )

        with with_langfuse() as langfuse_module:
            if langfuse_module is None:
                return
            try:
                # force_flush + joining the exporter threads is blocking work;
                # keep it off the event loop.
                await asyncio.to_thread(langfuse_module.get_client().shutdown)
                structlogger.debug("bot_builder.langfuse.shutdown.done")
            except Exception as exc:
                # Losing buffered traces is not worth failing a shutdown over.
                structlogger.warning(
                    "bot_builder.langfuse.shutdown.failed",
                    error_type=type(exc).__name__,
                )

    return app


def _apply_llm_overrides_from_builder_env() -> None:
    """Point OpenAI and Anthropic clients at the Hello LLM proxy when configured.

    Leaves any explicitly set provider credentials / base URLs untouched so local
    BYOK and test overrides keep working. Copilot v2 (and other builder LLM
    clients) then pick up the ambient env vars without special-casing the proxy.
    """
    if not config.HELLO_LLM_PROXY_BASE_URL:
        return

    config.apply_proxy_url(config.HELLO_LLM_PROXY_BASE_URL)

    structlogger.debug(
        "builder.main.using_llm_proxy", base_url=config.HELLO_LLM_PROXY_BASE_URL
    )

    if not config.RASA_PRO_LICENSE:
        structlogger.error(
            "copilot.proxy_missing_license",
            event_info=(
                "HELLO_LLM_PROXY_BASE_URL is set but RASA_PRO_LICENSE is missing."
            ),
        )
        return

    proxy_base = config.HELLO_LLM_PROXY_BASE_URL.rstrip("/")

    if not os.getenv("OPENAI_API_BASE") and not os.getenv("OPENAI_API_KEY"):
        # needed for litellm client
        os.environ["OPENAI_API_BASE"] = proxy_base
        # needed for openai async client
        os.environ["OPENAI_BASE_URL"] = proxy_base
        os.environ["OPENAI_API_KEY"] = config.RASA_PRO_LICENSE

    if (
        not os.getenv("ANTHROPIC_API_KEY")
        and not os.getenv("ANTHROPIC_BASE_URL")
        and not os.getenv("ANTHROPIC_AUTH_TOKEN")
    ):
        # Official Anthropic SDK posts to ``{base}/v1/messages``; the proxy
        # mounts Anthropic under ``/anthropic``. pydantic-ai's AnthropicProvider
        # requires ``ANTHROPIC_API_KEY`` (sent as ``x-api-key``). The proxy
        # gate checks ``Authorization: Bearer <license>`` first, so also send
        # that via ``ANTHROPIC_CUSTOM_HEADERS`` — the worker then replaces
        # ``x-api-key`` with the real Anthropic token before forwarding.
        os.environ["ANTHROPIC_BASE_URL"] = f"{proxy_base}/anthropic"
        os.environ["ANTHROPIC_API_KEY"] = config.RASA_PRO_LICENSE
        os.environ["ANTHROPIC_CUSTOM_HEADERS"] = (
            f"Authorization: Bearer {config.RASA_PRO_LICENSE}"
        )


def _wait_for_port(
    host: str, port: int, timeout: float, poll_interval: float = 0.1
) -> bool:
    """Wait until a port is accepting connections.

    Args:
        host: The host to connect to
        port: The port to check
        timeout: Maximum time to wait in seconds
        poll_interval: Time between connection attempts in seconds

    Returns:
        True if the port became available, False if timeout was reached
    """
    start_time = time.monotonic()
    while time.monotonic() - start_time < timeout:
        try:
            with socket.create_connection((host, port), timeout=1.0):
                return True
        except (OSError, socket.timeout):
            time.sleep(poll_interval)
    return False


def start_mcp_server(workspaces_root: str) -> None:
    """Start the MCP server in a background thread.

    The MCP server serves every agent workspace under `workspaces_root`: each
    tool call names the agent it acts on in its request `_meta`, and the server
    resolves that agent's folder for the call (see `_get_project_folder` in
    `rasa.builder.copilot.mcp_server.server`).

    Args:
        workspaces_root: Root folder holding one sub-folder per agent.
    """
    try:
        structlogger.info(
            "builder.main.starting_mcp_server",
            event_info="Starting MCP server in background thread",
            host=config.MCP_SERVER_HOST,
            port=config.MCP_SERVER_PORT,
            workspaces_root=workspaces_root,
        )

        from rasa.builder.copilot.mcp_server.server import run_server

        # Use the builder URL as the default Rasa server URL
        builder_url = (
            f"http://{config.BUILDER_SERVER_HOST}:{config.BUILDER_SERVER_PORT}"
        )
        run_server(
            host=config.MCP_SERVER_HOST,
            port=config.MCP_SERVER_PORT,
            workspaces_root=workspaces_root,
            rasa_server_url=builder_url,
        )

    except Exception as e:
        structlogger.error(
            "builder.main.mcp_server_startup_error",
            event_info="Failed to start MCP server",
            error=str(e),
        )


def main(workspaces_root: Optional[str] = None) -> None:
    """Main entry point.

    Args:
        workspaces_root: Folder holding one sub-folder per agent. A temporary
            folder is created when omitted.
    """
    try:
        # Setup logging
        setup_logging()

        # Setup telemetry
        rasa.telemetry.initialize_telemetry()
        rasa.telemetry.initialize_error_reporting(private_mode=False)

        _apply_llm_overrides_from_builder_env()

        # Setup langfuse (must run after proxy overrides so the proxy-derived host and
        # credentials are already in place)
        setup_langfuse()

        if config.HELLO_RASA_PROJECT_ID:
            # ensures long import times for modules are ahead of time
            warmup()

        if not workspaces_root:
            import tempfile

            workspaces_root = tempfile.mkdtemp(prefix="rasa_builder_")

        # Start MCP server in background thread
        mcp_thread = threading.Thread(
            target=start_mcp_server,
            args=(workspaces_root,),
            daemon=True,
            name="mcp-server",
        )
        mcp_thread.start()

        # Wait for MCP server to be ready before starting Sanic
        structlogger.info(
            "builder.main.waiting_for_mcp_server",
            event_info="Waiting for MCP server to accept connections",
            host=config.MCP_SERVER_HOST,
            port=config.MCP_SERVER_PORT,
            timeout=config.MCP_SERVER_STARTUP_TIMEOUT,
        )

        if _wait_for_port(
            config.MCP_SERVER_HOST,
            config.MCP_SERVER_PORT,
            config.MCP_SERVER_STARTUP_TIMEOUT,
        ):
            structlogger.info(
                "builder.main.mcp_server_ready",
                event_info="MCP server is ready to accept connections",
                host=config.MCP_SERVER_HOST,
                port=config.MCP_SERVER_PORT,
            )
        else:
            structlogger.error(
                "builder.main.mcp_server_startup_timeout",
                event_info="MCP server failed to start within timeout",
                host=config.MCP_SERVER_HOST,
                port=config.MCP_SERVER_PORT,
                timeout=config.MCP_SERVER_STARTUP_TIMEOUT,
            )
            raise RuntimeError(
                f"MCP server failed to start within "
                f"{config.MCP_SERVER_STARTUP_TIMEOUT}s timeout"
            )

        # Create and configure app
        app = create_app(workspaces_root)

        # Run the service
        structlogger.info(
            "service.starting",
            host=config.BUILDER_SERVER_HOST,
            port=config.BUILDER_SERVER_PORT,
        )

        app.run(
            host=config.BUILDER_SERVER_HOST,
            port=config.BUILDER_SERVER_PORT,
            single_process=True,
            motd=False,
        )

    except KeyboardInterrupt:
        print("\nService stopped by user")
        sys.exit(0)
    except Exception as e:
        print(f"Failed to start service: {e}")
        sys.exit(1)


if __name__ == "__main__":
    workspaces_root = sys.argv[1] if len(sys.argv) > 1 else None
    main(workspaces_root)
